11	// A row written by a pre-refactor build — same canonical fields, members in
12	// any order — must still decode and take part in retry comparison.
13	func TestLegacyStoredRowStillReadsAndCompares(t *testing.T) {
14		st, err := Open(filepath.Join(t.TempDir(), "legacy.db"))
15		if err != nil {
16			t.Fatalf("open: %v", err)
17		}
18		defer st.Close()
19	
20		// Member order scrambled relative to the canonical encoding; semantically
21		// the same content as the fresh submission below.
22		legacyJSON := `{"nodes":[{"labels":{"zone":"cn"},"memory":128,"cpu":200,"name":"n1"}],` +
23			`"selector":{"zone":"cn"},"resources":{"memory":64,"cpu":100},` +
24			`"priority":1,"queue":"q","name":"job","namespace":"ns"}`
25		if _, err := st.db.Exec(
26			"INSERT INTO placements (namespace, name, input_json, status, node, reason) VALUES (?, ?, ?, ?, ?, ?)",
27			"ns", "job", legacyJSON, "placed", "n1", nil,
28		); err != nil {
29			t.Fatalf("insert legacy row: %v", err)
30		}
31	
32		ctx := context.Background()
33		got, err := st.Get(ctx, "ns", "job")
34		if err != nil {
35			t.Fatalf("get legacy record: %v", err)
36		}
37		if got.Status != "placed" || got.Node == nil || *got.Node != "n1" || got.Queue != "q" {
38			t.Fatalf("legacy record decoded wrong: %+v", got)
39		}
40	
