package store

import (
	"context"
	"path/filepath"
	"testing"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
)

// A row written by a pre-refactor build — same canonical fields, members in
// any order — must still decode and take part in retry comparison.
func TestLegacyStoredRowStillReadsAndCompares(t *testing.T) {
	st, err := Open(filepath.Join(t.TempDir(), "legacy.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer st.Close()

	// Member order scrambled relative to the canonical encoding; semantically
	// the same content as the fresh submission below.
	legacyJSON := `{"nodes":[{"labels":{"zone":"cn"},"memory":128,"cpu":200,"name":"n1"}],` +
		`"selector":{"zone":"cn"},"resources":{"memory":64,"cpu":100},` +
		`"priority":1,"queue":"q","name":"job","namespace":"ns"}`
	if _, err := st.db.Exec(
		"INSERT INTO placements (namespace, name, input_json, status, node, reason) VALUES (?, ?, ?, ?, ?, ?)",
		"ns", "job", legacyJSON, "placed", "n1", nil,
	); err != nil {
		t.Fatalf("insert legacy row: %v", err)
	}

	ctx := context.Background()
	got, err := st.Get(ctx, "ns", "job")
	if err != nil {
		t.Fatalf("get legacy record: %v", err)
	}
	if got.Status != "placed" || got.Node == nil || *got.Node != "n1" || got.Queue != "q" {
		t.Fatalf("legacy record decoded wrong: %+v", got)
	}

	fresh := &Placement{
		Namespace: "ns", Name: "job", Queue: "q", Priority: 1,
		Resources: Resources{CPU: 100, Memory: 64},
		Selector:  map[string]string{"zone": "cn"},
		Nodes:     []Node{{Name: "n1", CPU: 200, Memory: 128, Labels: map[string]string{"zone": "cn"}}},
	}
	same, err := SameInput(fresh, got)
	if err != nil || !same {
		t.Fatalf("legacy record no longer compares equal: same=%v err=%v", same, err)
	}

	// A retry against the legacy identity must hit the unique identity and
	// return the stored record, never insert a second row.
	stored, created, err := st.Submit(ctx, fresh)
	if err != nil {
		t.Fatalf("submit retry: %v", err)
	}
	if created {
		t.Fatalf("retry against legacy identity inserted a new row")
	}
	if same, err := SameInput(stored, got); err != nil || !same {
		t.Fatalf("stored record changed by retry: same=%v err=%v", same, err)
	}
	recs, err := st.List(ctx, ListFilter{})
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(recs) != 1 {
		t.Fatalf("records = %d, want 1", len(recs))
	}
}

// New writes must keep the established stored format: input_json holds
// exactly the shared canonical encoding of the request half, so files written
// before and after the refactor are interchangeable.
func TestSubmitWritesCanonicalEncoding(t *testing.T) {
	st, err := Open(filepath.Join(t.TempDir(), "format.db"))
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer st.Close()

	p := &Placement{
		Namespace: "ns", Name: "job", Queue: "q", Priority: 1,
		Resources: Resources{CPU: 100, Memory: 64},
		Selector:  map[string]string{"zone": "cn"},
		Nodes:     []Node{{Name: "n1", CPU: 200, Memory: 128, Labels: map[string]string{"zone": "cn"}}},
		Status:    "placed",
	}
	if _, _, err := st.Submit(context.Background(), p); err != nil {
		t.Fatalf("submit: %v", err)
	}

	var inputJSON string
	if err := st.db.QueryRow(
		"SELECT input_json FROM placements WHERE namespace = ? AND name = ?", "ns", "job",
	).Scan(&inputJSON); err != nil {
		t.Fatalf("read stored row: %v", err)
	}
	want, err := model.CanonicalInput(p)
	if err != nil {
		t.Fatalf("canonical input: %v", err)
	}
	if inputJSON != string(want) {
		t.Fatalf("stored encoding changed:\n got: %s\nwant: %s", inputJSON, want)
	}
}

package api

import (
	"errors"
	"io"
	"net/http"
	"net/url"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/placement"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
)

// Error codes published by the placements API.
const (
	codeInvalidInput = "InvalidPlacementInputError"
	codeNotFound     = "PlacementNotFoundError"
	codeConflict     = "PlacementConflictError"
	codeStorageDown  = "storage_unavailable"
)

type placementHandler struct {
	svc *service.Service
}

func writeAPIError(c *gin.Context, status int, code, message string) {
	c.AbortWithStatusJSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// createPlacement handles POST /v1/placements. The transport layer only
// parses and validates the request and maps the business acceptance outcome
// to its HTTP status; scheduling and idempotency/conflict decisions belong to
// service.Accept. The strict parsing rules live in package placement and are
// shared with direct, non-HTTP callers.
func (h *placementHandler) createPlacement(c *gin.Context) {
	body, err := io.ReadAll(c.Request.Body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}
	p, err := placement.ParsePlacementInput(body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}

	stored, outcome, err := h.svc.Accept(c.Request.Context(), p)
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	switch outcome {
	case service.Created:
		c.JSON(http.StatusCreated, stored)
	case service.Identical:
		c.JSON(http.StatusOK, stored)
	case service.Conflict:
		writeAPIError(c, http.StatusConflict, codeConflict,
			"a placement with this namespace and name already exists with different content")
	}
}

// listPlacements handles GET /v1/placements, both the single-record form
// (namespace+name) and the filtered-list form. The transport layer only
// decodes the raw query string and maps the business result to its HTTP
// status; all parameter rules and filtering belong to service.Query.
func (h *placementHandler) listPlacements(c *gin.Context) {
	values, err := url.ParseQuery(c.Request.URL.RawQuery)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}

	result, err := h.svc.Query(c.Request.Context(), values)
	if errors.Is(err, service.ErrInvalidPlacementQuery) {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}
	if errors.Is(err, service.ErrPlacementNotFound) {
		writeAPIError(c, http.StatusNotFound, codeNotFound, "placement not found")
		return
	}
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	if result.Record != nil {
		c.JSON(http.StatusOK, result.Record)
		return
	}
	c.JSON(http.StatusOK, gin.H{"items": result.Items})
}

