311		// so the scheduling result must not stand in for content comparison.
312		placeable := &store.Placement{
313			Namespace: "ns", Name: "job", Queue: "q", Priority: 1,
314			Resources: store.Resources{CPU: 100, Memory: 64},
315			Selector:  map[string]string{},
