1	// Package fakestore provides an in-memory implementation of the storage
2	// contract defined by package service. It lets business-logic tests run the
3	// real accept and query flows without creating a SQLite file: stored records
4	// are controlled by the test, every call is recorded, and each method can be
5	// switched to fail with a chosen error. It carries no scheduling, defaulting
6	// or comparison rules of its own — those stay in package service.
7	package fakestore
8	
9	import (
10		"context"
11		"encoding/json"
12		"fmt"
13		"sort"
14		"sync"
15	
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
17	)
18	
19	// SubmitCall records one Submit invocation.
20	type SubmitCall struct {
21		// Record is a deep copy of the placement as the service submitted it,
22		// after its own normalization and trial scheduling.
23		Record *model.Placement
24	}
25	
26	// GetCall records one Get invocation.
27	type GetCall struct {
28		Namespace string
29		Name      string
30	}
31	
32	// Store is an in-memory storage double. The zero value is ready to use and
33	// safe for concurrent use.
34	//
35	// Its default behavior mirrors the storage guarantees the service relies on:
36	//   - Ping succeeds and is independently counted, so the HTTP health probe
37	//     can be failed with PingErr without touching any stored record;
38	//   - Submit keeps the first record stored for a (namespace, name) identity
39	//     and answers later submissions of that identity with the kept record
40	//     and created false;
41	//   - Get returns model.ErrNotFound for an unknown identity;
42	//   - List intersects the non-empty filter fields (a node filter never
43	//     matches a rejected record) and sorts by namespace then name in UTF-8
44	//     byte order.
45	//
46	// Setting PingErr, SubmitErr, GetErr or ListErr makes the matching method
47	// fail with that error instead of touching the in-memory records. Records
48	// can be preloaded with Seed, which is not counted as a call. Every Ping,
49	// Submit, Get and List invocation is appended to Pings, Submits, Gets
50	// and Lists.
51	type Store struct {
52		mu      sync.Mutex
53		records map[identity]*model.Placement
54		order   []identity
55	
56		PingErr   error
57		SubmitErr error
58		GetErr    error
59		ListErr   error
60	
61		Pings   int
62		Submits []SubmitCall
63		Gets    []GetCall
64		Lists   []model.ListFilter
65	}
66	
67	type identity struct {
68		namespace string
69		name      string
70	}
71	
72	// Seed preloads records as if they had been registered earlier, without
73	// recording calls. The first record for an identity wins, matching Submit.
74	func (s *Store) Seed(records ...*model.Placement) {
75		s.mu.Lock()
76		defer s.mu.Unlock()
77		for _, rec := range records {
78			id := identity{rec.Namespace, rec.Name}
79			if s.records == nil {
80				s.records = map[identity]*model.Placement{}
81			}
82			if _, ok := s.records[id]; ok {
83				continue
84			}
85			s.records[id] = clone(rec)
86			s.order = append(s.order, id)
87		}
88	}
89	
90	// Ping implements the service storage contract: it succeeds by default
91	// and fails with PingErr when the test needs the health probe to report
92	// the store unavailable. It never reads or mutates the stored records,
93	// and a failed Ping must not pre-empt the accept or query flows.
94	func (s *Store) Ping(_ context.Context) error {
95		s.mu.Lock()
96		defer s.mu.Unlock()
97		s.Pings++
98		return s.PingErr
99	}
100	
101	// Submit implements the service storage contract: it stores a copy of p the
102	// first time its identity is seen and otherwise returns the kept record.
103	func (s *Store) Submit(_ context.Context, p *model.Placement) (*model.Placement, bool, error) {
104		s.mu.Lock()
105		defer s.mu.Unlock()
106		s.Submits = append(s.Submits, SubmitCall{Record: clone(p)})
107		if s.SubmitErr != nil {
108			return nil, false, s.SubmitErr
109		}
110		id := identity{p.Namespace, p.Name}
111		if existing, ok := s.records[id]; ok {
112			return clone(existing), false, nil
113		}
114		if s.records == nil {
115			s.records = map[identity]*model.Placement{}
116		}
117		s.records[id] = clone(p)
118		s.order = append(s.order, id)
119		return clone(p), true, nil
120	}
121	
122	// Get implements the service storage contract: it returns a copy of the
123	// stored record or model.ErrNotFound for an unknown identity.
124	func (s *Store) Get(_ context.Context, namespace, name string) (*model.Placement, error) {
125		s.mu.Lock()
126		defer s.mu.Unlock()
127		s.Gets = append(s.Gets, GetCall{Namespace: namespace, Name: name})
128		if s.GetErr != nil {
129			return nil, s.GetErr
130		}
131		rec, ok := s.records[identity{namespace, name}]
132		if !ok {
133			return nil, model.ErrNotFound
134		}
135		return clone(rec), nil
136	}
137	
138	// List implements the service storage contract: it intersects the non-empty
139	// filter fields and returns copies sorted by namespace then name in UTF-8
140	// byte order. A node filter never matches a rejected record, whose Node is
141	// nil.
142	func (s *Store) List(_ context.Context, f model.ListFilter) ([]*model.Placement, error) {
143		s.mu.Lock()
144		defer s.mu.Unlock()
145		s.Lists = append(s.Lists, f)
146		if s.ListErr != nil {
147			return nil, s.ListErr
148		}
149		var out []*model.Placement
150		for _, id := range s.order {
151			rec := s.records[id]
152			if f.Namespace != "" && rec.Namespace != f.Namespace {
153				continue
154			}
155			if f.Queue != "" && rec.Queue != f.Queue {
156				continue
157			}
158			if f.Node != "" && (rec.Node == nil || *rec.Node != f.Node) {
159				continue
160			}
161			out = append(out, clone(rec))
162		}
163		sort.Slice(out, func(i, j int) bool {
164			if out[i].Namespace != out[j].Namespace {
165				return out[i].Namespace < out[j].Namespace
166			}
167			return out[i].Name < out[j].Name
168		})
169		return out, nil
170	}
171	
172	// clone deep-copies a record through its JSON form so the double never
173	// aliases a caller's or a stored struct. Placement only holds JSON-safe
174	// values, so encoding cannot fail.
175	func clone(p *model.Placement) *model.Placement {
176		data, err := json.Marshal(p)
177		if err != nil {
178			panic(fmt.Sprintf("fakestore: encode placement: %v", err))
179		}
180		var out model.Placement
181		if err := json.Unmarshal(data, &out); err != nil {
182			panic(fmt.Sprintf("fakestore: decode placement: %v", err))
183		}
184		return &out
185	}
186

